FLAGS = ("daily_coach_enabled", "weekly_review_enabled", "reengagement_enabled", "goal_nudge_enabled",
         "challenge_alerts_enabled", "meal_prompts_enabled")


def turn_on_for_everyone(apps, schema_editor):
    """Coach messages were opt-in and almost nobody had them. Turn them on for everyone (each person can
    turn any of them off again in the app's Settings) and give every account a settings row."""
    User = apps.get_model("accounts", "User")
    AutomationSettings = apps.get_model("automations", "AutomationSettings")
    AutomationSettings.objects.update(**{flag: True for flag in FLAGS})
    have = set(AutomationSettings.objects.values_list("user_id", flat=True))
    AutomationSettings.objects.bulk_create(
        [AutomationSettings(user_id=pk) for pk in User.objects.exclude(pk__in=have).values_list("pk", flat=True)],
        batch_size=500)



